/**
 * Redirects (ccm/redirects + /node/<nid>) and the /sites/default/files rewrite come from src/generated/routing.json,
 * regenerated by `migrate frontend generate` — edit the CCM / site config, not this list.
 */
import type { NextConfig } from "next";
import { existsSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";

type Routing = {
  redirects: { source: string; destination: string; statusCode: 301 | 302 | 303 | 307 | 308 }[];
  rewrites: { source: string; destination: string }[];
  /** live static source: directories of its scripts/styles — a file missing from public/ is fetched from the source */
  assetProxies?: { source: string; destination: string }[];
  /** Content-Type of extension-less public files (captured CDN renditions / icons), as recorded by the crawl */
  headers?: { source: string; headers: { key: string; value: string }[] }[];
};
const routing: Routing = JSON.parse(readFileSync(join(process.cwd(), "src/generated/routing.json"), "utf8"));

/** pnpm workspaces symlink node_modules into the monorepo root — let Turbopack/file tracing see it */
function workspaceRoot(start: string): string | undefined {
  let dir = resolve(start);
  for (;;) {
    if (existsSync(join(dir, "pnpm-workspace.yaml"))) return dir;
    const up = dirname(dir);
    if (up === dir) return undefined;
    dir = up;
  }
}
const root = workspaceRoot(process.cwd());

const nextConfig: NextConfig = {
  reactStrictMode: true,
  poweredByHeader: false,
  images: { unoptimized: true },
  ...(root ? { turbopack: { root }, outputFileTracingRoot: root } : {}),
  async redirects() {
    return routing.redirects.map((r) => ({ source: r.source, destination: r.destination, statusCode: r.statusCode }));
  },
  async rewrites() {
    // fallback: only when no page/public file matched (files copied into public/ win)
    return { beforeFiles: [], afterFiles: routing.assetProxies ?? [], fallback: routing.rewrites };
  },
  async headers() {
    return routing.headers ?? [];
  },
};

export default nextConfig;
